// Localized display names for the bundled workout catalog. The shared data
// (@fa/shared) keeps the English names as the source of truth; translations
// live in locales/<lang>/catalog.json keyed by id (English generated by
// scripts/exercise-catalog/gen-locale.ts). Every lookup falls back to the
// English catalog string, so a missing translation never shows a raw key.
import {
  getExercise,
  MACHINE_BY_ID,
  MUSCLE_GROUP_LABEL,
  MUSCLE_LABEL,
  MUSCLE_TARGET_LABEL,
  type Exercise,
} from "@fa/shared";

import i18n from "../i18n";

function lookup(section: string, id: string, fallback: string | undefined): string {
  return i18n.t(`catalog.${section}.${id}`, { defaultValue: fallback ?? id });
}

// snake_case id → "Title Case", for ids without a catalog label (the model can
// pass arbitrary ids) and other enum-ish keys shown to the user.
export function humanize(id: string): string {
  return id.replace(/_/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
}

export function exerciseName(ex: Exercise | string | null | undefined): string {
  if (!ex) return "";
  const e = typeof ex === "string" ? getExercise(ex) : ex;
  const id = typeof ex === "string" ? ex : ex.id;
  return e ? lookup("exercises", e.id, e.name) : humanize(id);
}

export function machineName(id: string): string {
  return lookup("machines", id, MACHINE_BY_ID[id]?.name);
}

export function muscleLabel(id: string): string {
  return lookup("muscles", id, MUSCLE_LABEL[id as keyof typeof MUSCLE_LABEL] ?? humanize(id));
}

export function muscleGroupLabel(id: string): string {
  return lookup("muscleGroups", id, MUSCLE_GROUP_LABEL[id as keyof typeof MUSCLE_GROUP_LABEL]);
}

export function muscleTargetLabel(id: string): string {
  return lookup("muscleTargets", id, MUSCLE_TARGET_LABEL[id]);
}

// Free-text search over an exercise: matches the localized name, the English
// name (people often know lifts by their English names) and the id.
export function exerciseMatches(ex: Exercise, query: string): boolean {
  const q = query.trim().toLowerCase();
  if (!q) return true;
  return (
    exerciseName(ex).toLowerCase().includes(q) ||
    ex.name.toLowerCase().includes(q) ||
    ex.id.includes(q)
  );
}
